/* The journey of a meal. Each step highlights a body part and moves the food
 * marker along a path (named waypoints in body-map.html). */
window.FOOD_JOURNEY = [
  { part: 'brain', at: 'mouth', time: 'Before the first bite', title: 'Seeing and smelling food',
    text: 'Just seeing, smelling or thinking about food makes the brain send signals down the vagus nerve. Your mouth waters and the stomach starts making acid — digestion begins before you eat (the “cephalic phase”).' },
  { part: 'mouth', at: 'mouth', time: '0–1 minute', title: 'Chewing and saliva',
    text: 'Teeth cut and grind the food. Saliva wets it and its enzyme amylase starts breaking starch into sugar. The tongue rolls it into a soft ball (bolus) and pushes it back.' },
  { part: 'throat', at: 'throat', time: '1 second', title: 'Swallowing',
    text: 'The epiglottis folds over the windpipe so the food goes down the food pipe, not into the lungs.' },
  { part: 'esophagus', at: 'esophagus', time: '5–10 seconds', title: 'Down the oesophagus',
    text: 'Waves of muscle (peristalsis) push the food down to the stomach. A ring of muscle at the bottom opens to let it in and closes to keep acid out.' },
  { part: 'stomach', at: 'stomach', time: '2–4 hours', title: 'Churning in the stomach',
    text: 'Strong acid kills germs and unfolds proteins, and the enzyme pepsin starts cutting them up. The muscular wall churns everything into a thick soup called chyme. Fatty meals stay longest.' },
  { part: 'pancreas', at: 'duodenum', time: 'As chyme arrives', title: 'Pancreas and gallbladder join in',
    text: 'The pancreas sprays in bicarbonate to neutralise the acid and enzymes for carbohydrate, protein and fat. The gallbladder squeezes in bile, which breaks fat into tiny droplets.' },
  { part: 'smallint', at: 'smallint', time: '2–6 hours', title: 'Absorption in the small intestine',
    text: 'Food is broken into its smallest pieces: sugars, amino acids, fatty acids. Millions of villi absorb them. Sugars and amino acids enter the blood; fats enter the lymph. About 90% of nutrients are absorbed here.' },
  { part: 'liver', at: 'liver', time: 'Minutes after absorption', title: 'The liver sorts the nutrients',
    text: 'Blood from the gut goes straight to the liver. It stores extra glucose as glycogen, builds proteins, packages fats, and neutralises toxins, alcohol and medicines before the blood reaches the rest of the body.' },
  { part: 'pancreas', at: 'pancreas', time: '30–60 minutes after eating', title: 'Insulin moves sugar into cells',
    text: 'As blood sugar rises, the pancreas releases insulin. Insulin opens the doors of muscle, fat and liver cells so they can take in glucose for energy now or store it for later.' },
  { part: 'vessels', at: 'heart', time: 'Continuously', title: 'Delivery to every cell',
    text: 'The heart pumps the nutrient-rich blood everywhere. Cells burn glucose and fat with oxygen to make ATP — the energy that powers muscles, the brain and every process — and release carbon dioxide and water.' },
  { part: 'largeint', at: 'largeint', time: '12–48 hours', title: 'Water saving in the large intestine',
    text: 'What cannot be digested — mainly fibre — reaches the colon. Trillions of gut bacteria ferment the fibre, making helpful fatty acids and vitamins, while the colon absorbs water and salts and forms stool.' },
  { part: 'kidneys', at: 'kidneys', time: 'All the time', title: 'The kidneys clean up',
    text: 'The kidneys filter the blood, remove urea (from protein) and extra salt and water, and send them to the bladder as urine.' },
  { part: 'largeint', at: 'rectum', time: '1–3 days after eating', title: 'Leaving the body',
    text: 'The rectum stores the stool until you go to the toilet. The whole trip usually takes between 1 and 3 days.' }
];

window.DRINK_JOURNEY = [
  { part: 'mouth', at: 'mouth', time: '0 seconds', title: 'Drinking',
    text: 'Liquid needs no chewing. Cold water also cools the mouth; sugary and acidic drinks bathe the teeth in sugar and acid.' },
  { part: 'esophagus', at: 'esophagus', time: 'About 1–2 seconds', title: 'Straight down',
    text: 'Liquids go down the oesophagus faster than food.' },
  { part: 'stomach', at: 'stomach', time: '10–30 minutes', title: 'A short stop in the stomach',
    text: 'Plain water leaves the stomach within minutes. Sugary, milky or fatty drinks stay longer. Alcohol starts being absorbed here — faster on an empty stomach.' },
  { part: 'smallint', at: 'smallint', time: '5–20 minutes after drinking', title: 'Absorbed into the blood',
    text: 'Most water is absorbed through the small intestine wall into the blood. Salt and a little sugar speed this up — which is why oral rehydration solution works so well when you are ill.' },
  { part: 'vessels', at: 'heart', time: 'Within 30 minutes', title: 'Water spreads through the body',
    text: 'About 60% of your body is water. It carries nutrients, cushions joints, cools you through sweat and keeps blood flowing. The brain senses how concentrated the blood is.' },
  { part: 'pituitary', at: 'brain', time: 'All the time', title: 'The brain checks the balance',
    text: 'If the blood is too concentrated, the pituitary releases ADH and you feel thirsty. If you drank plenty, ADH falls.' },
  { part: 'kidneys', at: 'kidneys', time: '30–60 minutes', title: 'The kidneys adjust',
    text: 'With little ADH, the kidneys let more water pass into the urine (pale urine). With lots of ADH they save water (dark urine). Caffeine and alcohol both make you pass more urine; alcohol blocks ADH.' },
  { part: 'bladder', at: 'bladder', time: '1–2 hours', title: 'Stored in the bladder',
    text: 'Urine collects until you feel the urge to go. Pale straw-coloured urine is a good sign you are drinking enough.' }
];

/* What happens to specific foods and drinks. */
window.NUTRIENTS = [
  ['🍞', 'Carbohydrates', 'Starch and sugars are broken into glucose (plus fructose and galactose). Glucose is the fast fuel for the brain and muscles; extra is stored as glycogen in the liver and muscles, and the rest turned into fat. Fibre isn’t digested but feeds gut bacteria and keeps you regular.', ['mouth', 'smallint', 'liver', 'pancreas', 'muscles']],
  ['🍗', 'Proteins', 'Broken into amino acids in the stomach and small intestine. The body uses them to build and repair muscles, enzymes, hormones and antibodies. Extra amino acids are burned for energy and their nitrogen becomes urea in the liver, removed by the kidneys.', ['stomach', 'smallint', 'liver', 'kidneys', 'muscles']],
  ['🥑', 'Fats', 'Bile breaks fat into droplets and lipase splits it into fatty acids and glycerol. They are repackaged and travel through the lymph into the blood. Fat is a rich energy store, builds cell walls and hormones, and carries vitamins A, D, E and K.', ['gallbladder', 'pancreas', 'smallint', 'lymph']],
  ['🥦', 'Vitamins & minerals', 'Absorbed mostly in the small intestine. Iron builds haemoglobin, calcium builds bones, vitamin C helps skin and immunity, B12 keeps nerves and blood healthy, iodine makes thyroid hormone.', ['smallint', 'liver', 'bones', 'thyroid']],
  ['🌾', 'Fibre', 'Not digested by our enzymes. Soluble fibre (oats, beans) forms a gel that slows sugar absorption and lowers cholesterol; insoluble fibre (whole grains, vegetables) adds bulk. Gut bacteria ferment it into short-chain fatty acids that feed the colon.', ['largeint', 'smallint']],
  ['💧', 'Water', 'Absorbed mostly in the small intestine, the rest in the colon. Most adults need about 1.5–2 litres of drinks a day, more in heat and exercise. The kidneys balance how much you keep.', ['smallint', 'largeint', 'kidneys', 'bladder']],
  ['☕', 'Caffeine (coffee, tea, energy drinks)', 'Absorbed within about 45 minutes. It blocks adenosine, the brain’s “sleepy” signal, so you feel alert; effects last 3–7 hours (half remains after about 5 hours), so afternoon caffeine can spoil sleep. Up to about 400 mg a day (3–4 cups of coffee) is fine for most adults; less in pregnancy and for teenagers.', ['brain', 'heart', 'kidneys']],
  ['🍷', 'Alcohol', 'Absorbed quickly through the stomach and small intestine — even faster on an empty stomach. The liver breaks it down at about one standard drink an hour; the in-between chemical, acetaldehyde, is toxic. Alcohol blocks ADH so you lose water, and in large amounts it depresses the brain and breathing. Less is better for health.', ['stomach', 'liver', 'brain', 'kidneys']],
  ['🥤', 'Sugary drinks', 'The sugar is absorbed very fast, causing a quick rise in blood sugar and insulin. Liquid calories don’t fill you up much, and the fructose is handled by the liver, where too much turns into fat. Acid and sugar also attack teeth.', ['mouth', 'pancreas', 'liver']],
  ['🥛', 'Milk', 'A mix of water, protein, fat, lactose sugar and calcium. Lactose needs the enzyme lactase — many adults worldwide make less of it (lactose intolerance). Milk leaves the stomach more slowly than water.', ['stomach', 'smallint', 'bones']]
];

/* Fasting stages (hours since the last meal). fuel = rough share of energy:
 * [food, glycogen, fat, ketones, protein]. */
window.FASTING = [
  { from: 0, to: 4, name: 'Fed state (absorbing)', parts: ['stomach', 'smallint', 'pancreas', 'liver'], fuel: [60, 10, 30, 0, 0],
    text: 'Food is being digested and absorbed. Blood sugar rises, insulin is high, and the body uses glucose from food while storing the extra as glycogen and fat.' },
  { from: 4, to: 12, name: 'Early fasting (post-absorptive)', parts: ['liver', 'pancreas', 'brain'], fuel: [15, 45, 40, 0, 0],
    text: 'The last meal is absorbed. Insulin falls and glucagon rises. The liver breaks down its glycogen to keep blood sugar steady for the brain. Fat burning slowly increases. This is where most people are every morning before breakfast.' },
  { from: 12, to: 18, name: 'Shift to fat burning', parts: ['liver', 'adrenals', 'muscles'], fuel: [0, 40, 55, 3, 2],
    text: 'Liver glycogen is running low. Fat cells release fatty acids, which muscles and the heart burn. The liver starts to turn some fat into ketones. Hunger usually comes in waves linked to your normal meal times, driven by ghrelin, and passes.' },
  { from: 18, to: 24, name: 'Glycogen nearly empty', parts: ['liver', 'kidneys', 'brain'], fuel: [0, 20, 62, 8, 10],
    text: 'Liver glycogen is mostly used up by about 24 hours. The liver (and the kidneys) now make new glucose (gluconeogenesis) from glycerol, lactate and amino acids. Ketone levels rise. Growth hormone rises, helping protect muscle.' },
  { from: 24, to: 48, name: 'Ketosis', parts: ['liver', 'brain', 'muscles'], fuel: [0, 5, 65, 18, 12],
    text: 'Ketones become an important fuel; the brain begins to use them, so it needs less glucose. Some protein is still broken down for glucose. Cells increase autophagy — recycling their own worn-out parts (mostly shown in animal studies). Tiredness, headache, dizziness and bad breath are common.' },
  { from: 48, to: 72, name: 'Deep ketosis', parts: ['brain', 'liver', 'kidneys'], fuel: [0, 2, 65, 25, 8],
    text: 'Ketones can supply a large share of the brain’s energy. The body saves protein by relying mostly on fat. Salt and water are lost, so dizziness on standing is common. Fasts this long should only be done with medical advice.' },
  { from: 72, to: 97, name: 'Prolonged fasting (medical only)', parts: ['brain', 'heart', 'muscles', 'kidneys'], fuel: [0, 0, 67, 27, 6],
    text: 'The metabolism slows a little to save energy. Risks rise: low salts (electrolytes) that can upset the heart rhythm, gout attacks, muscle loss and gallstones. Restarting food after a long fast must be gradual — “refeeding syndrome” can be dangerous.' }
];

window.FASTING_NOTES = [
  ['💧', 'Drink water while fasting', 'Going without water (dry fasting) is much riskier than going without food. The body can’t store water, so dehydration starts within a day: thirst, dark urine, headache, dizziness. Most people can only survive about 3 days without water, but several weeks without food.'],
  ['⚠️', 'Who should not fast without a doctor', 'Children and teenagers, pregnant or breastfeeding women, people with diabetes (especially on insulin or sulfonylureas), eating disorders, low body weight, kidney disease, gout, or those taking medicines that must be taken with food.'],
  ['🕒', 'Common fasting patterns', 'Overnight fasting (12 hours) is normal. Time-restricted eating (e.g. eating within 8–10 hours), 5:2 (two low-calorie days a week) and religious fasts like Ramadan (dawn to sunset). Studies show time-restricted eating can help weight and blood sugar for some people, mainly because they eat less overall.'],
  ['🍲', 'Breaking a fast well', 'Start with water and something gentle: soup, dates, fruit, yoghurt, then a normal balanced meal. Avoid a huge, very sugary or fatty meal straight away. After fasts longer than a few days, reintroduce food slowly with medical guidance.'],
  ['🚨', 'Stop and get help if…', 'You feel faint, confused, have a racing or irregular heartbeat, severe weakness, or (with diabetes) low or very high blood sugar. Drink something sugary if your blood sugar may be low, and get medical help.']
];

